CREATE TYPE "ProcessingStatus" AS ENUM ('pending', 'processing', 'completed', 'failed');
CREATE TABLE "Media" ("id" TEXT NOT NULL,"originalFilename" TEXT NOT NULL,"storedFilename" TEXT NOT NULL,"storagePath" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"fileSize" INTEGER NOT NULL,"width" INTEGER,"height" INTEGER,"fileHash" TEXT NOT NULL,"perceptualHash" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Media_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProcessingJob" ("id" TEXT NOT NULL,"mediaId" TEXT NOT NULL,"status" "ProcessingStatus" NOT NULL DEFAULT 'pending',"attempts" INTEGER NOT NULL DEFAULT 0,"errorCode" TEXT,"errorMessage" TEXT,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProcessingJob_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AnalysisResult" ("id" TEXT NOT NULL,"processingId" TEXT NOT NULL,"overallRisk" TEXT NOT NULL,"result" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AnalysisResult_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Media_storedFilename_key" ON "Media"("storedFilename"); CREATE UNIQUE INDEX "Media_storagePath_key" ON "Media"("storagePath"); CREATE UNIQUE INDEX "Media_fileHash_key" ON "Media"("fileHash"); CREATE INDEX "Media_perceptualHash_idx" ON "Media"("perceptualHash"); CREATE INDEX "ProcessingJob_mediaId_status_idx" ON "ProcessingJob"("mediaId","status"); CREATE UNIQUE INDEX "AnalysisResult_processingId_key" ON "AnalysisResult"("processingId"); ALTER TABLE "ProcessingJob" ADD CONSTRAINT "ProcessingJob_mediaId_fkey" FOREIGN KEY ("mediaId") REFERENCES "Media"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AnalysisResult" ADD CONSTRAINT "AnalysisResult_processingId_fkey" FOREIGN KEY ("processingId") REFERENCES "ProcessingJob"("id") ON DELETE CASCADE ON UPDATE CASCADE;
